```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"log"

	"github.com/segmentio/kafka-go/schemav2/schema"
)

func main() {
	if len(os.Args) != 3 {
		log.Fatal("Usage: go run script.go <input_file> <struct_name>")
	}

	inputFile := os.Args[1]
	structName := os.Args[2]

	file, err := parser.ParseFile(token.NewFileSet(), inputFile, nil, parser.ParseComments)
	if err != nil {
		log.Fatalf("failed to parse input file: %v", err)
	}

	var structDef ast.Struct
	ast.Inspect(file, func(n ast.Node) bool {
		switch n.(type) {
		case *ast.Struct:
			structDef = n.(*ast.Struct)
			return false
		default:
			return true
		}
	})

	if structDef == nil {
		log.Fatalf("No struct found in file %s", inputFile)
	}

	// Generate Avro schema based on the struct's fields
	schemaBytes, err := json.Marshal(structDef.Fields)
	if err != nil {
		log.Fatalf("Failed to marshal struct fields: %v", err)
	}

	fmt.Println(string(schemaBytes))
	fmt.Println()

	// Write the generated schema to a file named "struct.avsc"
	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), schemaBytes, 0644)
	if err != nil {
		log.Fatalf("Failed to write Avro schema: %v", err)
	}
}
```

### How to Use This Program

1. **Compile the Program**: Save the code into a file named `script.go` and compile it using the following command:
   ```sh
   go build -o script ./script.go
   ```

2. **Run the Program**: When you run the compiled program with your Go source file and the name of the struct, it will print out the Avro schema.

For example, if you have a Go source file `mystruct.go` containing:
```go
package mypackage

type MyStruct struct {
	ID int    `json:"id"`
	Name string `json:"name"`
}
```
And you run the program like this:
```sh
./script mystruct.go MyStruct
```
The output will include the Avro schema for the `MyStruct` type.

